struct Geometry {int mx,my,w,h;uint64_t slots;};
static Geometry geometry(int w,int h){int mx=int(std::ceil(w*.04)),my=int(std::ceil(h*.04));return {mx,my,w-2*mx,h-2*my,uint64_t(std::max(0,w-2*mx))*std::max(0,h-2*my)*3};}
