static int denseBit(const Image& im,const Geometry& g,uint64_t slot){auto p=slot/3;return im.bit(int(g.mx+p%g.w),int(g.my+p/g.w),int(slot%3));}
static void denseBit(Image& im,const Geometry& g,uint64_t slot,int v){auto p=slot/3;im.bit(int(g.mx+p%g.w),int(g.my+p/g.w),int(slot%3),v);}
static std::pair<uint64_t,uint64_t> order(const std::string& key,const Bytes& nonce,uint64_t count){auto seed=hmac(derive(key,"dense-positions",nonce,true),bytes("positions"));auto start=read(seed,0,8)%count,step=read(seed,8,8)%count;if(!step)step=1;while(std::gcd(step,count)!=1){step=(step+1)%count;if(!step)step=1;}return {start,step};}
